PHA
ORA #$01 ; _local_Gfx_drawChar_bit 0 = 1 -> ROM _at $C000 - $FFFF
STA PORTB
; Lower RAMTOP ( $6A ) so the OS allocates the screen+
; display list BELOW our main code region .xe / xt put
; main code _at $A000+; xl spans through $9FFF and
; doesn ' _local_Gfx_line_t leave room for an OS - managed GR .8 screen,
; so xl programs need _a different setup ( tracked
; separately ) .RAMTOP = page $A0 ( = byte $A000 )
; tells the OS that usable RAM ends _at $A000 ; the
; OS picks screen _at $9FFF - 8 KB = $8000 for GR .8,
; with the display list just below .The OS also
; recomputes MEMTOP _local_Stdio_putChar_off RAMTOP automatically .
LDA #$A0
STA $6A ; RAMTOP
