; chain entry .Then A = 7 for VVBLKD = XITVBV .
; Without this the OS ' _s S : open leaves $0222 zeroed
; on this OS revision and the next VBI dies in _a
; JMP ( $0222 ) -> $0000 -> BRK loop .
LDY #< SYSVBV
LDX #> SYSVBV
LDA #$06 ; immediate VBI ( = VVBLKI slot )
JSR SETVBV
LDY #< XITVBV
LDX #> XITVBV
LDA #$07 ; deferred VBI ( = VVBLKD slot )
JSR SETVBV
; The OS placed the GR .8 display list _at ~ $7F xx
; ( just below the screen _at $8000 - $9FFF ) .xtc heap
; on xe starts _at heapTop = $7FFF and grows down,
; so the next new - expression would land on top of
; the OS - managed display list .Lower HP ( xtc heap
; pointer ; $86 / HI resolves the right ZP slot
; per target ) to $7E00 so subsequent allocations
; clear the 256 - byte DL .APPMHI ( OS - tracked floor )
; gets the same value to keep CIO from growing into
; the heap .
LDA #$00
STA $86
LDA #$7E
STA $87
LDA #$00
STA $0E ; APPMHI _local_Stdio_printStruct_lo
LDA #$7E
STA $0F ; APPMHI _local_Stdio_printStruct_hi
; Restore PORTB and re - enable VBI .
PLA
STA PORTB
PLA
STA $D40E ; restore NMIEN
CLI
