; Copy the static full - screen DL from __gfx8_dlist into
; $8000 - the 256 - byte gap before the screen RAM _at
; $8100 .$8000 is $400 - aligned so ANTIC ' _s DL fetcher
; never trips its 1 KB - wrap quirk regardless of where
; the linker placed the static scratch .The static DL
; is 202 bytes ( 3 BLANK+LMS+95+LMS+95+JVB ) ;
; copy 203 to also drag along the JVB target padding .
LDA #__gfx8_dlist
STA $B0
LDA #__gfx8_dlist
STA $B1
LDA #$00
STA $B2
LDA #$80
STA $B3
LDX #203
LDY #$00
_gfx8_native_copy :
LDA ( $B0 ),Y
STA ( $B2 ),Y
INY
DEX
BNE _gfx8_native_copy
; Patch the JVB target in the $8000 copy back to itself .
; JVB opcode is _at _local_Stdio_setCursor_offset 199,target _local_Gfx8_readFromOS_lo / _local_Gfx8_readFromOS_hi _at 200 / 201 .
LDA #$00
STA $80C8 ; $8000+200 ( JVB target _local_Gfx8_readFromOS_lo )
LDA #$80
STA $80C9 ; $8000+201 ( JVB target _local_Gfx8_readFromOS_hi )
; Disable display while we reconfigure .
LDA #$00
STA $D400 ; DMACTL = no display
; Point ANTIC+OS shadow _at the $8000 DL .
LDA #$00
STA $0230 ; SDLSTL
STA $D402 ; DLISTL
LDA #$80
STA $0231 ; SDLSTH
STA $D403 ; DLISTH
; SAVMSC = $8100 ( so any readFromOS ( ) sees the same
; _base the DL ' _s first LMS uses ) .
LDA #$00
STA $58
LDA #$81
STA $59
; CHACTL default+character _base .
LDA #$02
STA $D401 ; CHACTL
; Re - enable display : playfield normal width,normal
; DMA,no PMG,instructions fetched .
LDA #$22
STA $D400 ; DMACTL
